styles:
*:focus:not(.focus-visible) {
             outline: none !important;
           }
           *:focus-visible {
             /* remove default focus style */
             outline: none !important;
             /* custom focus styles */
             box-shadow: 0 0 2px 2px #58bbff !important;
             color: lime
           }
           #Helios-width-full #lighting .hd-controls li{
               opacity: 0.8;
           }
           #Helios-width-full .function_tab li a{
                   color: #b4b4b4;
           }
           #Helios-width-full p.note{
                   color: #ffffff !important;
           }
           #Helios-width-full #Helios-cable .info a,
           #Helios-width-full #Helios-cable .info a:hover{
               color: #99d6ff !important;
               border: 1px #99d6ff solid !important;
           }
           #Helios-width-full #Helios-colorarea .hd_sec_spec ul li p{
               color: #c5e8ff !important;
           }
           #Helios-width-full #Helios-KV:before {
               content: '';
               display: block;
               width: 100%;
               height: 100%;
               position: absolute;
               left: 0%;
               background: rgba(0, 0, 0, 0.5);
               top: 0;
               z-index: 0;
               pointer-events: none;
           }
           #Helios-width-full #Helios-KV .icons_ul,
           #Helios-width-full #Helios-KV .mainfull .info{
               position: relative;
           }
           #Helios-width-full #compare__bottom .compare_picbox a{
               display: inline-block;
           }
